<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {workspace,createGitProject} from '$lib/stores/workspace';import {infraState,infraCommand} from '$lib/infra/store';import {goto} from '$app/navigation';
 let show=false,name='',url='',branch='main',domain='',error='',notice='';
 $: repos=$workspace.projects.filter(p=>p.source==='GitHub');$: domains=$workspace.domains.filter(d=>!d.project);
 async function add(){try{error='';const id=createGitProject(name,url,branch,domain);show=false;await goto('/projects/'+id+'/overview');}catch(e){error=e instanceof Error?e.message:'Import preview failed.';}}
 function auto(id:string,value:boolean){try{infraCommand({type:'auto-deploy',project:id,enabled:value});error='';notice='Auto-deploy preference saved locally. No webhook was created.';}catch(e){error=e instanceof Error?e.message:'Setting unavailable.';}}
</script>
<Heading title="Git" subtitle="Link GitHub repositories to projects. No account connection is required for this preview."><button class="btn primary" on:click={()=>show=!show}><Icon name="Plus"/> Import from GitHub</button></Heading>
<div class="stack"><div class="callout"><strong>Repository access is not connected yet.</strong><p>Enter a public GitHub URL to create a draft. Drevanta does not fetch files, authenticate to GitHub, build commits or configure webhooks in this frontend.</p></div>
{#if show}<form class="card stack" on:submit|preventDefault={add}><h3>Import repository</h3><div class="grid2"><label class="field">Project name<input required bind:value={name} maxlength="80" placeholder="My frontend"/></label><label class="field">Branch<input required bind:value={branch} maxlength="100" placeholder="main"/></label></div><label class="field">GitHub repository URL<input type="url" required bind:value={url} placeholder="https://github.com/owner/repository"/></label><label class="field">Website address (optional)<select bind:value={domain}><option value="">Automatic project address</option>{#each domains as d}<option value={d.id}>{d.name}</option>{/each}</select></label><small>This creates a project draft. Repository authentication and automatic builds are not yet available.</small>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button type="button" class="btn secondary" on:click={()=>show=false}>Cancel</button><button class="btn primary" type="submit">Create project draft</button></div></form>{/if}{#if !show&&error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card table-card"><div class="table-head"><h3>GitHub projects</h3><p class="subtitle">Repositories registered in this workspace.</p></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Repository</th><th>Branch</th><th>Auto-deploy</th><th></th></tr></thead><tbody>{#each repos as p (p.id)}<tr><td><a class="link-btn" href={'/projects/'+p.id+'/overview'}>{p.name}</a></td><td class="mono native-path">{p.repo}</td><td class="mono">{p.branch}</td><td><label class="check"><input type="checkbox" checked={$infraState.autoDeploy[p.id]||false} on:change={(e)=>auto(p.id,e.currentTarget.checked)}/> { $infraState.autoDeploy[p.id]?'Preference on':'Preference off'}</label></td><td><a class="btn secondary small" href={'/projects/'+p.id+'/settings'}>Settings</a></td></tr>{:else}<tr><td colspan="5">No GitHub projects. Import a repository to create a draft.</td></tr>{/each}</tbody></table></div></section></div>
